                                                    </div>
                                                    <p className="text-xs text-muted-foreground mb-2">
                                                        {onceTasks.length} tasks → Product Management epic
                                                    </p>
                                                    <div className="flex flex-wrap gap-1">
                                                        {onceTasks.map((t: any, i: number) => (
                                                            <Badge key={i} variant="outline" className="text-xs">
                                                                {t.title}
                                                            </Badge>
                                                        ))}
                                                    </div>
