                        <Button 
                            variant="outline" 
                            size="sm" 
                            type="button"
                            onClick={() => {
                                setCurrentTask({ 
                                    title: "", 
                                    description: "", 
                                    defaultPriority: "Medium", 
                                    defaultEstimateHours: 1, 
                                    requiredRole: "Development" 
                                });
                                setIsTaskFormOpen(true);
