import { useState, useRef, useEffect, useMemo } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Calendar } from "@/components/ui/calendar";
import { 
  Clock, 
  Flag, 
  User, 
  Check,
  Pencil,
  ChevronDown
} from "lucide-react";
import { cn } from "@/lib/utils";
import { format, isValid, parseISO } from "date-fns";
import { EFFORT_VALUES } from "@shared/schema";

function safeParseDate(dateStr: string | undefined): Date | null {
  if (!dateStr) return null;
  try {
    const date = typeof dateStr === 'string' ? parseISO(dateStr) : new Date(dateStr);
    return isValid(date) ? date : null;
  } catch {
    return null;
  }
}

function formatDate(date: Date | null, formatStr: string): string {
  if (!date) return "No date";
  try {
    return format(date, formatStr);
  } catch {
    return "Invalid";
  }
}

export type LayoutVariant = "one-column" | "two-column" | "three-column";

const STATUS_OPTIONS = ["Todo", "In Progress", "Review", "Done"];

const STATUS_COLORS: Record<string, string> = {
  "Todo": "bg-slate-100 text-slate-700 border-slate-200 hover:bg-slate-200",
  "In Progress": "bg-blue-100 text-blue-700 border-blue-200 hover:bg-blue-200",
  "Review": "bg-amber-100 text-amber-700 border-amber-200 hover:bg-amber-200",
  "Done": "bg-green-100 text-green-700 border-green-200 hover:bg-green-200"
};

const PRIORITY_COLORS: Record<string, string> = {
  "High": "text-red-600 bg-red-50",
  "Medium": "text-amber-600 bg-amber-50",
  "Low": "text-slate-600 bg-slate-50"
};

export interface TaskCardTask {
  id: string;
  title: string;
  status: string;
  priority: string;
  assigneeId?: string;
  deadline: string;
  effort?: number;
  epicId?: string;
  stageId?: string;
  milestoneId?: string;
}

export interface TaskCardProps {
  task: TaskCardTask;
  epicName?: string;
  stageName?: string;
  milestoneName?: string;
  assigneeName?: string;
  users?: Array<{ id: string; name: string }>;
  stages?: Array<{ id: string; name: string }>;
  layoutVariant?: LayoutVariant;
  onUpdateTask: (taskId: string, updates: Partial<TaskCardTask>) => void;
  onOpenEpic?: (epicId: string) => void;
  onOpenMilestone?: (milestoneId: string) => void;
  onOpenTask?: (taskId: string) => void;
}

export function TaskCard({
  task,
  epicName,
  stageName,
  milestoneName,
  assigneeName,
  users = [],
  stages = [],
  layoutVariant = "three-column",
  onUpdateTask,
  onOpenEpic,
  onOpenMilestone,
  onOpenTask
}: TaskCardProps) {
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState(task.title);
  const [datePopoverOpen, setDatePopoverOpen] = useState(false);
  const [assigneePopoverOpen, setAssigneePopoverOpen] = useState(false);
  const titleInputRef = useRef<HTMLInputElement>(null);

  const deadlineDate = useMemo(() => safeParseDate(task.deadline), [task.deadline]);
  const isOverdue = deadlineDate && deadlineDate < new Date() && task.status !== "Done";

  useEffect(() => {
    if (isEditingTitle && titleInputRef.current) {
      titleInputRef.current.focus();
      titleInputRef.current.select();
    }
  }, [isEditingTitle]);

  const handleTitleSave = () => {
    if (editedTitle.trim() && editedTitle !== task.title) {
      onUpdateTask(task.id, { title: editedTitle.trim() });
    } else {
      setEditedTitle(task.title);
    }
    setIsEditingTitle(false);
  };

  const handleTitleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      handleTitleSave();
    } else if (e.key === "Escape") {
      setEditedTitle(task.title);
      setIsEditingTitle(false);
    }
  };

  const handleStatusChange = (newStatus: string) => {
    onUpdateTask(task.id, { status: newStatus });
  };

  const handleAssigneeChange = (userId: string) => {
    onUpdateTask(task.id, { assigneeId: userId === "unassigned" ? undefined : userId });
    setAssigneePopoverOpen(false);
  };

  const handleDateChange = (date: Date | undefined) => {
    if (date) {
      onUpdateTask(task.id, { deadline: date.toISOString().split('T')[0] });
    }
    setDatePopoverOpen(false);
  };

  const handleEffortChange = (effort: string) => {
    onUpdateTask(task.id, { effort: parseInt(effort) });
  };

  const isCompact = layoutVariant === "three-column";
  const isWide = layoutVariant === "one-column";

  return (
    <Card 
      className={cn(
        "group transition-all hover:shadow-md border-l-4",
        task.status === "Done" ? "border-l-green-500" : "border-l-primary/50",
        isWide && "flex flex-row items-stretch"
      )}
      data-testid={`task-card-${task.id}`}
    >
      <CardContent className={cn(
        "p-3 space-y-2",
        isWide && "flex-1 flex flex-row items-center gap-4 p-4"
      )}>
        {isWide ? (
          <>
            {/* Wide Layout - Single Row */}
            <div className="flex items-center gap-3 min-w-0 flex-1">
              {/* Status Dropdown */}
              <Select value={task.status} onValueChange={handleStatusChange}>
                <SelectTrigger 
                  className={cn("h-7 w-[110px] text-xs border-0 font-medium", STATUS_COLORS[task.status])}
                  aria-label="Change status"
                  onClick={(e) => e.stopPropagation()}
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {STATUS_OPTIONS.map(s => (
                    <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {/* Epic Context */}
              {epicName && (
                <button 
                  className="text-xs text-muted-foreground hover:text-purple-600 hover:underline truncate max-w-[100px] shrink-0"
                  onClick={(e) => { e.stopPropagation(); onOpenEpic?.(task.epicId!); }}
                  aria-label={`Open epic ${epicName}`}
                >
                  {epicName}
                </button>
              )}

              {/* Title (Editable) */}
              <div className="flex-1 min-w-0">
                {isEditingTitle ? (
                  <Input
                    ref={titleInputRef}
                    value={editedTitle}
                    onChange={(e) => setEditedTitle(e.target.value)}
                    onBlur={handleTitleSave}
                    onKeyDown={handleTitleKeyDown}
                    className="h-7 text-sm font-medium"
                    aria-label="Edit task title"
                  />
                ) : (
                  <button
                    className="text-left w-full font-medium text-sm truncate hover:text-primary group-hover:underline"
                    onClick={(e) => { e.stopPropagation(); onOpenTask?.(task.id); }}
                    onDoubleClick={(e) => { e.stopPropagation(); setIsEditingTitle(true); }}
                    aria-label={`Task: ${task.title}. Double-click to edit.`}
                  >
                    {task.title}
                  </button>
                )}
              </div>
            </div>

            {/* Right side controls */}
            <div className="flex items-center gap-3 shrink-0">
              {/* Milestone */}
              {milestoneName && (
                <button
                  className="flex items-center gap-1 text-xs text-amber-600 hover:underline"
                  onClick={(e) => { e.stopPropagation(); onOpenMilestone?.(task.milestoneId!); }}
                  aria-label={`Milestone: ${milestoneName}`}
                >
                  <Flag className="h-3 w-3" />
                  <span className="truncate max-w-[80px]">{milestoneName}</span>
                </button>
              )}

              {/* Effort */}
              <Select value={task.effort?.toString() || ""} onValueChange={handleEffortChange}>
                <SelectTrigger 
                  className="h-7 w-[60px] text-xs"
                  onClick={(e) => e.stopPropagation()}
                  aria-label="Change effort estimate"
                >
                  <SelectValue placeholder="—" />
                </SelectTrigger>
                <SelectContent>
                  {EFFORT_VALUES.map(v => (
                    <SelectItem key={v} value={v.toString()} className="text-xs">{v} pts</SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {/* Due Date */}
              <Popover open={datePopoverOpen} onOpenChange={setDatePopoverOpen}>
                <PopoverTrigger asChild>
                  <Button
                    variant="ghost"
                    size="sm"
                    className={cn(
                      "h-7 text-xs gap-1 px-2",
                      isOverdue && "text-red-500"
                    )}
                    onClick={(e) => e.stopPropagation()}
                    aria-label={`Due date: ${formatDate(deadlineDate, "MMM d, yyyy")}`}
                  >
                    <Clock className="h-3 w-3" />
                    {formatDate(deadlineDate, "MMM d")}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="end">
                  <Calendar
                    mode="single"
                    selected={deadlineDate || undefined}
                    onSelect={handleDateChange}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>

              {/* Assignee */}
              <Popover open={assigneePopoverOpen} onOpenChange={setAssigneePopoverOpen}>
                <PopoverTrigger asChild>
                  <Button 
                    variant="ghost" 
                    size="sm" 
                    className="h-7 px-2 gap-1.5"
                    onClick={(e) => e.stopPropagation()}
                    aria-label={assigneeName ? `Assigned to ${assigneeName}` : "Unassigned"}
                  >
                    {assigneeName ? (
                      <>
                        <Avatar className="h-5 w-5">
                          <AvatarFallback className="text-[9px]">
                            {assigneeName.substring(0, 2).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <span className="text-xs max-w-[60px] truncate">{assigneeName.split(' ')[0]}</span>
                      </>
                    ) : (
                      <>
                        <User className="h-4 w-4 text-muted-foreground" />
                        <span className="text-xs text-muted-foreground">Assign</span>
                      </>
                    )}
                    <ChevronDown className="h-3 w-3 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-48 p-1" align="end">
                  <div className="space-y-0.5">
                    <button
                      className="w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted flex items-center gap-2"
                      onClick={() => handleAssigneeChange("unassigned")}
                    >
                      <User className="h-4 w-4 text-muted-foreground" />
                      Unassigned
                      {!task.assigneeId && <Check className="h-4 w-4 ml-auto" />}
                    </button>
                    {users.map(u => (
                      <button
                        key={u.id}
                        className="w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted flex items-center gap-2"
                        onClick={() => handleAssigneeChange(u.id)}
                      >
                        <Avatar className="h-5 w-5">
                          <AvatarFallback className="text-[9px]">{u.name.substring(0, 2).toUpperCase()}</AvatarFallback>
                        </Avatar>
                        {u.name}
                        {task.assigneeId === u.id && <Check className="h-4 w-4 ml-auto" />}
                      </button>
                    ))}
                  </div>
                </PopoverContent>
              </Popover>

              {/* Stage */}
              {stageName && (
                <Badge variant="outline" className="text-[10px] shrink-0">{stageName}</Badge>
              )}

              {/* Priority Badge */}
              <Badge className={cn("text-[10px] px-1.5 shrink-0", PRIORITY_COLORS[task.priority])}>
                {task.priority}
              </Badge>
            </div>
          </>
        ) : (
          <>
            {/* Compact/Grid Layout - Stacked Rows */}
            {/* Top Row: Status only */}
            <div className="flex items-center justify-end">
              <Select value={task.status} onValueChange={handleStatusChange}>
                <SelectTrigger 
                  className={cn("h-6 w-auto min-w-[80px] text-[10px] border-0 font-medium px-1.5", STATUS_COLORS[task.status])}
                  onClick={(e) => e.stopPropagation()}
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {STATUS_OPTIONS.map(s => (
                    <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Middle Row: Title with Epic below */}
            <div className="relative group/title">
              {isEditingTitle ? (
                <Input
                  ref={titleInputRef}
                  value={editedTitle}
                  onChange={(e) => setEditedTitle(e.target.value)}
                  onBlur={handleTitleSave}
                  onKeyDown={handleTitleKeyDown}
                  className="h-7 text-sm font-medium"
                />
              ) : (
                <div className="flex items-start gap-1">
                  <div className="flex-1 min-w-0">
                    <button
                      className="text-left font-medium text-sm leading-tight line-clamp-2 hover:text-primary w-full"
                      onClick={(e) => { e.stopPropagation(); onOpenTask?.(task.id); }}
                      onDoubleClick={(e) => { e.stopPropagation(); setIsEditingTitle(true); }}
                    >
                      {task.title}
                    </button>
                    {epicName && (
                      <button 
                        className="text-[11px] text-muted-foreground hover:text-purple-600 truncate block max-w-full mt-0.5"
                        onClick={(e) => { e.stopPropagation(); onOpenEpic?.(task.epicId!); }}
                      >
                        {epicName}
                      </button>
                    )}
                  </div>
                  <Button 
                    variant="ghost" 
                    size="icon" 
                    className="h-5 w-5 opacity-0 group-hover/title:opacity-100 shrink-0"
                    onClick={(e) => { e.stopPropagation(); setIsEditingTitle(true); }}
                  >
                    <Pencil className="h-3 w-3" />
                  </Button>
                </div>
              )}
            </div>

            {/* Milestone Row (if exists) */}
            {milestoneName && (
              <button
                className="flex items-center gap-1 text-[10px] text-amber-600 hover:underline"
                onClick={(e) => { e.stopPropagation(); onOpenMilestone?.(task.milestoneId!); }}
              >
                <Flag className="h-2.5 w-2.5" />
                {milestoneName}
              </button>
            )}

            {/* Bottom Row: Assignee, Date, Effort, Priority */}
            <div className="flex items-center justify-between pt-2 border-t border-border/50 gap-2">
              {/* Assignee */}
              <Popover open={assigneePopoverOpen} onOpenChange={setAssigneePopoverOpen}>
                <PopoverTrigger asChild>
                  <button 
                    className="flex items-center gap-1.5 text-xs hover:text-primary"
                    onClick={(e) => e.stopPropagation()}
                  >
                    {assigneeName ? (
                      <>
                        <Avatar className="h-5 w-5">
                          <AvatarFallback className="text-[9px]">
                            {assigneeName.substring(0, 2).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <span className="text-muted-foreground truncate max-w-[60px]">{assigneeName.split(' ')[0]}</span>
                      </>
                    ) : (
                      <span className="text-muted-foreground italic text-xs">Assign</span>
                    )}
                  </button>
                </PopoverTrigger>
                <PopoverContent className="w-48 p-1" align="start">
                  <div className="space-y-0.5">
                    <button
                      className="w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted flex items-center gap-2"
                      onClick={() => handleAssigneeChange("unassigned")}
                    >
                      <User className="h-4 w-4 text-muted-foreground" />
                      Unassigned
                      {!task.assigneeId && <Check className="h-4 w-4 ml-auto" />}
                    </button>
                    {users.map(u => (
                      <button
                        key={u.id}
                        className="w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted flex items-center gap-2"
                        onClick={() => handleAssigneeChange(u.id)}
                      >
                        <Avatar className="h-5 w-5">
                          <AvatarFallback className="text-[9px]">{u.name.substring(0, 2).toUpperCase()}</AvatarFallback>
                        </Avatar>
                        {u.name}
                        {task.assigneeId === u.id && <Check className="h-4 w-4 ml-auto" />}
                      </button>
                    ))}
                  </div>
                </PopoverContent>
              </Popover>

              {/* Stage */}
              {stageName && (
                <Badge variant="outline" className="text-[10px] shrink-0">{stageName}</Badge>
              )}

              <div className="flex items-center gap-2">
                {/* Effort */}
                {!isCompact && (
                  <Select value={task.effort?.toString() || ""} onValueChange={handleEffortChange}>
                    <SelectTrigger 
                      className="h-6 w-[50px] text-[10px] px-1"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <SelectValue placeholder="—" />
                    </SelectTrigger>
                    <SelectContent>
                      {EFFORT_VALUES.map(v => (
                        <SelectItem key={v} value={v.toString()} className="text-xs">{v}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}

                {/* Due Date */}
                <Popover open={datePopoverOpen} onOpenChange={setDatePopoverOpen}>
                  <PopoverTrigger asChild>
                    <button
                      className={cn(
                        "flex items-center gap-1 text-xs",
                        isOverdue 
                          ? "text-red-500 font-medium" 
                          : "text-muted-foreground"
                      )}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <Clock className="h-3 w-3" />
                      {formatDate(deadlineDate, "MMM d")}
                    </button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="end">
                    <Calendar
                      mode="single"
                      selected={deadlineDate || undefined}
                      onSelect={handleDateChange}
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>

                {/* Priority */}
                <Badge className={cn("text-[10px] px-1 h-5", PRIORITY_COLORS[task.priority])}>
                  {task.priority}
                </Badge>
              </div>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/project/task-filte.content:
import { useState, useEffect } from "react";
import { X, Filter, RotateCcw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

export interface TaskFilters {
  statuses: string[];
  priorities: string[];
  stageIds: string[];
  epicIds: string[];
  assigneeIds: string[];
  sprintIds: string[];
  dueDateRange: { from: string; to: string } | null;
}

interface Stage {
  id: string;
  name: string;
}

interface Epic {
  id: string;
  title: string;
}

interface User {
  id: string;
  name: string;
}

interface Sprint {
  id: string;
  name: string;
}

interface TaskFilterModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  filters: TaskFilters;
  onFiltersChange: (filters: TaskFilters) => void;
  stages: Stage[];
  epics: Epic[];
  users: User[];
  sprints?: Sprint[];
}

const STATUS_OPTIONS = ["Todo", "In Progress", "Review", "Done"];
const PRIORITY_OPTIONS = ["Low", "Medium", "High", "Critical"];

export function TaskFilterModal({
  open,
  onOpenChange,
  filters,
  onFiltersChange,
  stages,
  epics,
  users,
  sprints = [],
}: TaskFilterModalProps) {
  const [localFilters, setLocalFilters] = useState<TaskFilters>(filters);

  useEffect(() => {
    setLocalFilters(filters);
  }, [filters, open]);

  const handleStatusToggle = (status: string) => {
    const updated = localFilters.statuses.includes(status)
      ? localFilters.statuses.filter(s => s !== status)
      : [...localFilters.statuses, status];
    setLocalFilters({ ...localFilters, statuses: updated });
  };

  const handlePriorityToggle = (priority: string) => {
    const updated = localFilters.priorities.includes(priority)
      ? localFilters.priorities.filter(p => p !== priority)
      : [...localFilters.priorities, priority];
    setLocalFilters({ ...localFilters, priorities: updated });
  };

  const handleStageToggle = (stageId: string) => {
    const updated = localFilters.stageIds.includes(stageId)
      ? localFilters.stageIds.filter(s => s !== stageId)
      : [...localFilters.stageIds, stageId];
    setLocalFilters({ ...localFilters, stageIds: updated });
  };

  const handleEpicToggle = (epicId: string) => {
    const updated = localFilters.epicIds.includes(epicId)
      ? localFilters.epicIds.filter(e => e !== epicId)
      : [...localFilters.epicIds, epicId];
    setLocalFilters({ ...localFilters, epicIds: updated });
  };

  const handleAssigneeToggle = (assigneeId: string) => {
    const updated = localFilters.assigneeIds.includes(assigneeId)
      ? localFilters.assigneeIds.filter(a => a !== assigneeId)
      : [...localFilters.assigneeIds, assigneeId];
    setLocalFilters({ ...localFilters, assigneeIds: updated });
  };

  const handleSprintToggle = (sprintId: string) => {
    const updated = localFilters.sprintIds.includes(sprintId)
      ? localFilters.sprintIds.filter(s => s !== sprintId)
      : [...localFilters.sprintIds, sprintId];
    setLocalFilters({ ...localFilters, sprintIds: updated });
  };

  const handleResetFilters = () => {
    setLocalFilters({
      statuses: [],
      priorities: [],
      stageIds: [],
      epicIds: [],
      assigneeIds: [],
      sprintIds: [],
      dueDateRange: null,
    });
  };

  const handleApplyFilters = () => {
    onFiltersChange(localFilters);
    onOpenChange(false);
  };

  const activeFilterCount = 
    localFilters.statuses.length +
    localFilters.priorities.length +
    localFilters.stageIds.length +
    localFilters.epicIds.length +
    localFilters.assigneeIds.length +
    (localFilters.dueDateRange ? 1 : 0);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Filter className="h-5 w-5" />
            Filter Tasks
          </DialogTitle>
          <DialogDescription>
            Apply filters to narrow down your task list
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Status Filter */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">Status</Label>
            <div className="flex flex-wrap gap-2">
              {STATUS_OPTIONS.map((status) => (
                <Badge
                  key={status}
                  variant={localFilters.statuses.includes(status) ? "default" : "outline"}
                  className={cn(
                    "cursor-pointer transition-colors px-3 py-1.5",
                    localFilters.statuses.includes(status) 
                      ? "bg-primary text-primary-foreground" 
                      : "hover:bg-muted"
                  )}
                  onClick={() => handleStatusToggle(status)}
                  data-testid={`filter-status-${status}`}
                >
                  {status}
                </Badge>
              ))}
            </div>
          </div>

          {/* Priority Filter */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">Priority</Label>
            <div className="flex flex-wrap gap-2">
              {PRIORITY_OPTIONS.map((priority) => (
                <Badge
                  key={priority}
                  variant={localFilters.priorities.includes(priority) ? "default" : "outline"}
                  className={cn(
                    "cursor-pointer transition-colors px-3 py-1.5",
                    localFilters.priorities.includes(priority)
                      ? priority === "Critical" ? "bg-red-600 text-white"
                        : priority === "High" ? "bg-orange-500 text-white"
                        : priority === "Medium" ? "bg-blue-500 text-white"
                        : "bg-slate-500 text-white"
                      : "hover:bg-muted"
                  )}
                  onClick={() => handlePriorityToggle(priority)}
                  data-testid={`filter-priority-${priority}`}
                >
                  {priority}
                </Badge>
              ))}
            </div>
          </div>

          {/* Stage Filter */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">Stage</Label>
            <div className="flex flex-wrap gap-2">
              {stages.map((stage) => (
                <Badge
                  key={stage.id}
                  variant={localFilters.stageIds.includes(stage.id) ? "default" : "outline"}
                  className={cn(
                    "cursor-pointer transition-colors px-3 py-1.5",
                    localFilters.stageIds.includes(stage.id) 
                      ? "bg-primary text-primary-foreground" 
                      : "hover:bg-muted"
                  )}
                  onClick={() => handleStageToggle(stage.id)}
                  data-testid={`filter-stage-${stage.id}`}
                >
                  {stage.name}
                </Badge>
              ))}
            </div>
          </div>

          {/* Epic Filter */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">Epic</Label>
            <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
              {epics.map((epic) => (
                <Badge
                  key={epic.id}
                  variant={localFilters.epicIds.includes(epic.id) ? "default" : "outline"}
                  className={cn(
                    "cursor-pointer transition-colors px-3 py-1.5",
                    localFilters.epicIds.includes(epic.id) 
                      ? "bg-primary text-primary-foreground" 
                      : "hover:bg-muted"
                  )}
                  onClick={() => handleEpicToggle(epic.id)}
                  data-testid={`filter-epic-${epic.id}`}
                >
                  {epic.title}
                </Badge>
              ))}
            </div>
          </div>

          {/* Assignee Filter */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">Assignee</Label>
            <div className="flex flex-wrap gap-2">
              <Badge
                variant={localFilters.assigneeIds.includes("unassigned") ? "default" : "outline"}
                className={cn(
                  "cursor-pointer transition-colors px-3 py-1.5",
                  localFilters.assigneeIds.includes("unassigned") 
                    ? "bg-primary text-primary-foreground" 
                    : "hover:bg-muted"
                )}
                onClick={() => handleAssigneeToggle("unassigned")}
                data-testid="filter-assignee-unassigned"
              >
                Unassigned
              </Badge>
              {users.map((user) => (
                <Badge
                  key={user.id}
                  variant={localFilters.assigneeIds.includes(user.id) ? "default" : "outline"}
                  className={cn(
                    "cursor-pointer transition-colors px-3 py-1.5",
                    localFilters.assigneeIds.includes(user.id) 
                      ? "bg-primary text-primary-foreground" 
                      : "hover:bg-muted"
                  )}
                  onClick={() => handleAssigneeToggle(user.id)}
                  data-testid={`filter-assignee-${user.id}`}
                >
                  {user.name}
                </Badge>
              ))}
            </div>
          </div>

          {/* Sprint Filter */}
          {sprints.length > 0 && (
            <div className="space-y-3">
              <Label className="text-sm font-medium">Sprint</Label>
              <div className="flex flex-wrap gap-2">
                <Badge
                  variant={localFilters.sprintIds.includes("backlog") ? "default" : "outline"}
                  className={cn(
                    "cursor-pointer transition-colors px-3 py-1.5",
                    localFilters.sprintIds.includes("backlog") 
                      ? "bg-primary text-primary-foreground" 
                      : "hover:bg-muted"
                  )}
                  onClick={() => handleSprintToggle("backlog")}
                  data-testid="filter-sprint-backlog"
                >
                  Backlog
                </Badge>
                {sprints.map((sprint) => (
                  <Badge
                    key={sprint.id}
                    variant={localFilters.sprintIds.includes(sprint.id) ? "default" : "outline"}
                    className={cn(
                      "cursor-pointer transition-colors px-3 py-1.5",
                      localFilters.sprintIds.includes(sprint.id) 
                        ? "bg-primary text-primary-foreground" 
                        : "hover:bg-muted"
                    )}
                    onClick={() => handleSprintToggle(sprint.id)}
                    data-testid={`filter-sprint-${sprint.id}`}
                  >
                    {sprint.name}
                  </Badge>
                ))}
              </div>
            </div>
          )}

          {/* Due Date Range */}
          <div className="space-y-3">
            <Label className="text-sm font-medium">Due Date</Label>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">From</Label>
                <Input
                  type="date"
                  value={localFilters.dueDateRange?.from || ""}
                  onChange={(e) => setLocalFilters({
                    ...localFilters,
                    dueDateRange: {
                      from: e.target.value,
                      to: localFilters.dueDateRange?.to || ""
                    }
                  })}
                  data-testid="filter-date-from"
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">To</Label>
                <Input
                  type="date"
                  value={localFilters.dueDateRange?.to || ""}
                  onChange={(e) => setLocalFilters({
                    ...localFilters,
                    dueDateRange: {
                      from: localFilters.dueDateRange?.from || "",
                      to: e.target.value
                    }
                  })}
                  data-testid="filter-date-to"
                />
              </div>
            </div>
          </div>
        </div>

        <DialogFooter className="flex justify-between sm:justify-between">
          <Button 
            variant="ghost" 
            onClick={handleResetFilters}
            className="gap-2"
            data-testid="button-reset-filters"
          >
            <RotateCcw className="h-4 w-4" />
            Reset
          </Button>
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => onOpenChange(false)} data-testid="button-cancel-filters">
              Cancel
            </Button>
            <Button onClick={handleApplyFilters} data-testid="button-apply-filters">
              Apply Filters
              {activeFilterCount > 0 && (
                <Badge variant="secondary" className="ml-2 h-5 px-1.5">
                  {activeFilterCount}
                </Badge>
              )}
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function getActiveFilterCount(filters: TaskFilters): number {
  return (
    filters.statuses.length +
    filters.priorities.length +
    filters.stageIds.length +
    filters.epicIds.length +
    filters.assigneeIds.length +
    filters.sprintIds.length +
    (filters.dueDateRange && (filters.dueDateRange.from || filters.dueDateRange.to) ? 1 : 0)
  );
}

export const emptyFilters: TaskFilters = {
  statuses: [],
  priorities: [],
  stageIds: [],
  epicIds: [],
  assigneeIds: [],
  sprintIds: [],
  dueDateRange: null,
};

